// ── Tools ──────────────────────────────────────────────────────────────────────

[McpServerToolType]
public static class MyTools
{
    [McpServerTool(Name = "echo"), System.ComponentModel.Description("Echoes input back")]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool(Name = "add"), System.ComponentModel.Description("Adds two numbers")]
    public static double Add(double a, double b) => a + b;
}

// ── Resources ──────────────────────────────────────────────────────────────────

[McpServerResourceType]
public static class MyResources
{
    /// <summary>Returns application configuration data.</summary>
    [McpServerResource(UriTemplate = "config://app", Name = "app-config", MimeType = "application/json")]
    public static string GetAppConfig()
    {
        var config = new
        {
            Environment = "production",
            MaxRetries  = 3,
            Timeout     = "30s",
            Features    = new[] { "logging", "caching", "auth" }
        };
        return System.Text.Json.JsonSerializer.Serialize(config);
    }

    /// <summary>Returns server health and version info.</summary>
    [McpServerResource(UriTemplate = "config://health", Name = "health-status", MimeType = "application/json")]
    public static string GetHealthStatus()
    {
        var status = new
        {
            Status  = "healthy",
            Uptime  = Environment.TickCount64 / 1000,
            Version = "1.0.0"
        };
        return System.Text.Json.JsonSerializer.Serialize(status);
    }
}

